-- The v0.5.13 retcon (migration 0087, generated by `cargo jackioh patches retcon --from v0.5.13`, issue
-- #3631, SPEC §11 R3631001). Runs after 51_fleet_track.sql; profiles 1 and 2 are active by then.
\set ON_ERROR_STOP on

-- As 38 does for 0068: every row the suite seeds carries a name the retcon keeps, so the migration
-- renamed nothing when run.sh applied it; this check seeds rows under the v0.5.13 line's old names,
-- as production holds them, applies the migration again over them, and rolls back. One old name is
-- the start of the others (v0.5.13 in v0.5.13b), so each row must be renamed exactly once, and a name
-- is never read inside a longer one. This file spells old names on purpose: the retcon's tree
-- rewrite skips it.

\echo '### R3631001: the v0.5.13 retcon renames each row''s catalog version once ###'
begin;
do $$
declare
  p1 constant uuid := '11111111-1111-1111-1111-111111111111';
  p2 constant uuid := '22222222-2222-2222-2222-222222222222';
  rec_of constant text := '{"pilots": {"p1": "ai", "p2": "ai"}, "game": {"turns": 9}, "versions": 3}';
begin
  insert into public.cards (id, card_index, name, set_id, type, tags, rarity, token, cost, catalog_version)
  values ('r3631-a', '3631.1', 'Card under v0.5.13h', 'Core', 'Unit', '{}', 'Common', false, '1'::jsonb, 'v0.5.13h'),
         ('r3631-b', '3631.2', 'Card under v0.5.13', 'Core', 'Unit', '{}', 'Common', false, '1'::jsonb, 'v0.5.13'),
         ('r3631-c', '3631.3', 'Card under v0.5.12z', 'Core', 'Unit', '{}', 'Common', false, '1'::jsonb, 'v0.5.12z');
  update app.settings set value = '"v0.5.13h"' where key = 'catalog_version';
  perform set_config('r3631.grants', (select count(*)::text from public.collection_grants), true);

  insert into public.decks (id, profile_id, name, cards, catalog_version)
  values ('d3631000-0000-4000-8000-000000000001', p1, 'Under v0.5.13h', '["core-001"]', 'v0.5.13h');
  insert into public.matches (id, status, seed, p1_profile_id, p2_profile_id, p1_deck, p2_deck,
                              catalog_version, ceiling_at, started_at, ended_at)
  values ('e3631000-0000-4000-8000-000000000001', 'over', 'r3631-1', p1, p2, '[]', '[]', 'v0.5.13', now(), now(), now()),
         ('e3631000-0000-4000-8000-000000000002', 'over', 'r3631-2', p1, p2, '[]', '[]', 'v0.5.13b', now(), now(), now());

  -- Development ids whose versions start one another, a learned series of a renamed version, a live
  -- record, and a record of a kept version.
  insert into public.game_records (id, source, mode, patch, record, folded)
  select g.id, g.source, 'random', g.patch,
         rec_of::jsonb || jsonb_build_object('id', g.id, 'source', g.source, 'mode', 'random', 'patch', g.patch),
         false
    from (values ('e3631000-0000-4000-8000-0000000000aa', 'live', 'v0.5.13h'),
                 ('dev:v0.5.13:r3631:1', 'dev', 'v0.5.13'),
                 ('dev:v0.5.13b:r3631:1', 'dev', 'v0.5.13b'),
                 ('dev:v0.5.13b:learned-v0.5.13-20261110-1:2', 'dev', 'v0.5.13b'),
                 ('dev:v0.5.12z:r3631:1', 'dev', 'v0.5.12z')) as g (id, source, patch);

  -- The totals key on the patch: the old v0.5.13's row and the old v0.5.13b's must not meet.
  insert into public.record_totals (patch, source, mode, p1_pilot, p2_pilot, records)
  values ('v0.5.13', 'dev', 'random', 'ai', 'ai', 13), ('v0.5.13b', 'dev', 'random', 'ai', 'ai', 14);
  insert into public.game_totals (patch, source, mode, p1_pilot, p2_pilot, total)
  values ('v0.5.13', 'dev', 'random', 'ai', 'ai', '{"games": 13}'),
         ('v0.5.13b', 'dev', 'random', 'ai', 'ai', '{"games": 14}');
  -- A card's co-played map keeps the record where two cards first met: renamed as the record is,
  -- v0.5.13 never read inside v0.5.13b.
  insert into public.card_totals (patch, source, mode, pilot, card, stats, co)
  values ('v0.5.13b', 'dev', 'random', 'ai', 'core-001', '{"n": 14}',
          '{"core-002": [1, 1, "dev:v0.5.13b:learned-v0.5.13-20261110-1:2", 0, 0], "core-003": [1, 0, "e3631000-0000-4000-8000-0000000000aa", 1, 2]}'),
         ('v0.5.13', 'dev', 'random', 'ai', 'core-001', '{"n": 13}', '{"core-002": [1, 1, "dev:v0.5.13:r3631:1", 0, 0]}'),
         ('v0.5.12z', 'dev', 'random', 'ai', 'core-001', '{"n": 12}', '{"core-002": [1, 1, "dev:v0.5.12z:r3631:1", 0, 0]}');
  insert into public.decklist_totals (patch, list, deck, games, wins, first_record, first_seat)
  values ('v0.5.13b', 'l3631', '[]', 14, 7, 'dev:v0.5.13b:r3631:1', 0),
         ('v0.5.13', 'l3631', '[]', 13, 6, 'dev:v0.5.13:r3631:1', 1);
end $$;

\i /tmp/0087_v0_5_13_retcon.sql

do $$
declare
  v text;
  n int;
begin
  if app.catalog_version() <> 'v0.5.12ah' then
    raise exception 'FAIL (R3631001): the live version is %, expected v0.5.12ah', app.catalog_version();
  end if;
  if (select count(*)::text from public.collection_grants) <> current_setting('r3631.grants') then
    raise exception 'FAIL (R3631001): the rename granted cards';
  end if;
  select string_agg(id || '=' || catalog_version, ',' order by id) into v from public.cards where id like 'r3631-%';
  if v <> 'r3631-a=v0.5.12ah,r3631-b=v0.5.12aa,r3631-c=v0.5.12z' then
    raise exception 'FAIL (R3631001): the cards are %', v;
  end if;
  if (select catalog_version from public.decks where id = 'd3631000-0000-4000-8000-000000000001') <> 'v0.5.12ah' then
    raise exception 'FAIL (R3631001): the deck saved under v0.5.13h was not renamed once';
  end if;
  select string_agg(catalog_version, ',' order by seed) into v from public.matches where seed like 'r3631-%';
  if v <> 'v0.5.12aa,v0.5.12ab' then
    raise exception 'FAIL (R3631001): the matches are % (r3631-1, r3631-2)', v;
  end if;

  select string_agg(id || '=' || patch, ',' order by id) into v from public.game_records
   where (id like 'dev:%r3631%' or id = 'e3631000-0000-4000-8000-0000000000aa') and patch <> 'v0.5.12z';
  if v <> 'dev:v0.5.12aa:r3631:1=v0.5.12aa,dev:v0.5.12ab:r3631:1=v0.5.12ab,e3631000-0000-4000-8000-0000000000aa=v0.5.12ah' then
    raise exception 'FAIL (R3631001): the game records are %', v;
  end if;
  if not exists (select 1 from public.game_records where id = 'dev:v0.5.12ab:learned-v0.5.12aa-20261110-1:2' and patch = 'v0.5.12ab') then
    raise exception 'FAIL (R3631001): a learned series'' version was not renamed with the record''s';
  end if;
  if (select record -> 'versions' from public.game_records where id = 'dev:v0.5.12z:r3631:1') <> '3'::jsonb then
    raise exception 'FAIL (R3631001): a record of a kept version was rewritten';
  end if;
  select count(*) into n from public.game_records
   where (id like 'dev:%r3631%' or id like 'dev:%learned-v0.5.12a%' or id = 'e3631000-0000-4000-8000-0000000000aa')
     and patch <> 'v0.5.12z'
     and (record ->> 'id' <> id or record ->> 'patch' <> patch or record -> 'versions' <> '4'::jsonb
          or record #>> '{game,turns}' <> '9');
  if n <> 0 then
    raise exception 'FAIL (R3631001): % records'' copies do not match their row, or lost their detail', n;
  end if;
  if exists (select 1 from public.game_records where id like 'dev:~%') then
    raise exception 'FAIL (R3631001): a record kept its passing name';
  end if;

  select string_agg(patch || '=' || records, ',' order by patch) into v from public.record_totals
   where patch in ('v0.5.12aa', 'v0.5.12ab', 'v0.5.13', 'v0.5.13b');
  if v <> 'v0.5.12aa=13,v0.5.12ab=14' then
    raise exception 'FAIL (R3631001): the record totals are %', v;
  end if;
  select string_agg(patch || '=' || (total ->> 'games'), ',' order by patch) into v from public.game_totals
   where patch in ('v0.5.12aa', 'v0.5.12ab', 'v0.5.13', 'v0.5.13b');
  if v <> 'v0.5.12aa=13,v0.5.12ab=14' then
    raise exception 'FAIL (R3631001): the game totals are %', v;
  end if;
  if exists (select 1 from public.game_totals where starts_with(patch, '~')) then
    raise exception 'FAIL (R3631001): a game total kept its passing name';
  end if;
  select string_agg(patch || '=' || (stats ->> 'n') || ':' || (co #>> '{core-002,2}'), ',' order by patch) into v
    from public.card_totals where card = 'core-001' and patch in ('v0.5.12z', 'v0.5.12aa', 'v0.5.12ab', 'v0.5.13', 'v0.5.13b');
  if v <> 'v0.5.12aa=13:dev:v0.5.12aa:r3631:1,v0.5.12ab=14:dev:v0.5.12ab:learned-v0.5.12aa-20261110-1:2,v0.5.12z=12:dev:v0.5.12z:r3631:1' then
    raise exception 'FAIL (R3631001): the card totals are %', v;
  end if;
  if (select co #>> '{core-003,2}' from public.card_totals where card = 'core-001' and patch = 'v0.5.12ab') <> 'e3631000-0000-4000-8000-0000000000aa' then
    raise exception 'FAIL (R3631001): a live record id in a co-played map changed';
  end if;
  select string_agg(patch || '=' || games || ':' || first_record, ',' order by patch) into v
    from public.decklist_totals where list = 'l3631';
  if v <> 'v0.5.12aa=13:dev:v0.5.12aa:r3631:1,v0.5.12ab=14:dev:v0.5.12ab:r3631:1' then
    raise exception 'FAIL (R3631001): the decklist totals are %', v;
  end if;
  raise notice 'OK (R3631001): every row renamed once, the copies kept and marked 4, a name never read inside a longer one, a kept version left alone';
end $$;
rollback;
